// One note made from 32 parallel sine components at harmonics 1..32.
module synth_additive32 (
    input wire clk,
    input wire sample_tick,
    input wire gate,
    input wire [31:0] phase_step,
    output reg signed [15:0] sample = 16'sd0
);
    localparam [2:0] IDLE=0, ATTACK=1, DECAY=2, SUSTAIN=3, RELEASE=4;
    localparam [15:0] SUSTAIN_LEVEL=16'd32768;
    localparam [15:0] ATTACK_STEP=16'd1024;
    localparam [15:0] DECAY_STEP=16'd8;
    localparam [15:0] RELEASE_STEP=16'd4;

    // Harmonic frequency steps are generated by an addition chain.
    wire [31:0] s01=phase_step, s02=s01+phase_step, s03=s02+phase_step, s04=s03+phase_step;
    wire [31:0] s05=s04+phase_step, s06=s05+phase_step, s07=s06+phase_step, s08=s07+phase_step;
    wire [31:0] s09=s08+phase_step, s10=s09+phase_step, s11=s10+phase_step, s12=s11+phase_step;
    wire [31:0] s13=s12+phase_step, s14=s13+phase_step, s15=s14+phase_step, s16=s15+phase_step;
    wire [31:0] s17=s16+phase_step, s18=s17+phase_step, s19=s18+phase_step, s20=s19+phase_step;
    wire [31:0] s21=s20+phase_step, s22=s21+phase_step, s23=s22+phase_step, s24=s23+phase_step;
    wire [31:0] s25=s24+phase_step, s26=s25+phase_step, s27=s26+phase_step, s28=s27+phase_step;
    wire [31:0] s29=s28+phase_step, s30=s29+phase_step, s31=s30+phase_step, s32=s31+phase_step;
    wire signed [15:0] w01,w02,w03,w04,w05,w06,w07,w08,w09,w10,w11,w12,w13,w14,w15,w16;
    wire signed [15:0] w17,w18,w19,w20,w21,w22,w23,w24,w25,w26,w27,w28,w29,w30,w31,w32;
    additive_component c01(clk,sample_tick,gate,s01,w01); additive_component c02(clk,sample_tick,gate,s02,w02);
    additive_component c03(clk,sample_tick,gate,s03,w03); additive_component c04(clk,sample_tick,gate,s04,w04);
    additive_component c05(clk,sample_tick,gate,s05,w05); additive_component c06(clk,sample_tick,gate,s06,w06);
    additive_component c07(clk,sample_tick,gate,s07,w07); additive_component c08(clk,sample_tick,gate,s08,w08);
    additive_component c09(clk,sample_tick,gate,s09,w09); additive_component c10(clk,sample_tick,gate,s10,w10);
    additive_component c11(clk,sample_tick,gate,s11,w11); additive_component c12(clk,sample_tick,gate,s12,w12);
    additive_component c13(clk,sample_tick,gate,s13,w13); additive_component c14(clk,sample_tick,gate,s14,w14);
    additive_component c15(clk,sample_tick,gate,s15,w15); additive_component c16(clk,sample_tick,gate,s16,w16);
    additive_component c17(clk,sample_tick,gate,s17,w17); additive_component c18(clk,sample_tick,gate,s18,w18);
    additive_component c19(clk,sample_tick,gate,s19,w19); additive_component c20(clk,sample_tick,gate,s20,w20);
    additive_component c21(clk,sample_tick,gate,s21,w21); additive_component c22(clk,sample_tick,gate,s22,w22);
    additive_component c23(clk,sample_tick,gate,s23,w23); additive_component c24(clk,sample_tick,gate,s24,w24);
    additive_component c25(clk,sample_tick,gate,s25,w25); additive_component c26(clk,sample_tick,gate,s26,w26);
    additive_component c27(clk,sample_tick,gate,s27,w27); additive_component c28(clk,sample_tick,gate,s28,w28);
    additive_component c29(clk,sample_tick,gate,s29,w29); additive_component c30(clk,sample_tick,gate,s30,w30);
    additive_component c31(clk,sample_tick,gate,s31,w31); additive_component c32(clk,sample_tick,gate,s32,w32);

    // Bright low harmonics and quieter high harmonics keep the sum bounded.
    wire signed [20:0] sum32 =
        ($signed({{5{w01[15]}},w01}) >>> 2) +
        ($signed({{5{w02[15]}},w02}) >>> 3) + ($signed({{5{w03[15]}},w03}) >>> 3) +
        ($signed({{5{w04[15]}},w04}) >>> 4) + ($signed({{5{w05[15]}},w05}) >>> 4) +
        ($signed({{5{w06[15]}},w06}) >>> 4) +
        ($signed({{5{w07[15]}},w07}) >>> 5) + ($signed({{5{w08[15]}},w08}) >>> 5) +
        ($signed({{5{w09[15]}},w09}) >>> 6) + ($signed({{5{w10[15]}},w10}) >>> 6) +
        ($signed({{5{w11[15]}},w11}) >>> 6) + ($signed({{5{w12[15]}},w12}) >>> 6) +
        ($signed({{5{w13[15]}},w13}) >>> 7) + ($signed({{5{w14[15]}},w14}) >>> 7) +
        ($signed({{5{w15[15]}},w15}) >>> 7) + ($signed({{5{w16[15]}},w16}) >>> 7) +
        ($signed({{5{w17[15]}},w17}) >>> 8) + ($signed({{5{w18[15]}},w18}) >>> 8) +
        ($signed({{5{w19[15]}},w19}) >>> 8) + ($signed({{5{w20[15]}},w20}) >>> 8) +
        ($signed({{5{w21[15]}},w21}) >>> 8) + ($signed({{5{w22[15]}},w22}) >>> 8) +
        ($signed({{5{w23[15]}},w23}) >>> 8) + ($signed({{5{w24[15]}},w24}) >>> 8) +
        ($signed({{5{w25[15]}},w25}) >>> 9) + ($signed({{5{w26[15]}},w26}) >>> 9) +
        ($signed({{5{w27[15]}},w27}) >>> 9) + ($signed({{5{w28[15]}},w28}) >>> 9) +
        ($signed({{5{w29[15]}},w29}) >>> 9) + ($signed({{5{w30[15]}},w30}) >>> 9) +
        ($signed({{5{w31[15]}},w31}) >>> 9) + ($signed({{5{w32[15]}},w32}) >>> 9);

    // Every component already has its own phase and ADSR state. The final
    // divide keeps the weighted 32-term sum inside the 16-bit I2S sample.
    always @(posedge clk) begin
        if (sample_tick) sample <= sum32 >>> 1;
    end
endmodule
